// Analytic eroded-mountain relief (the Advanced Terrain Erosion filter).
//
// The mountain belts of the density field can carry relief generated by an
// ANALYTIC erosion filter instead of simulated erosion: a directional stripe
// noise ("Phacelle noise") aligned with the terrain slope carves branching
// gullies and leaves sharp ridges between them, evaluated per point in
// isolation - no water state, no global pass - so streaming chunks of any
// size sample the same eroded field at any order and any thread count.
//
// The filter is a faithful double-precision port of the Advanced Terrain
// Erosion filter by Rune Skovbo Johansen
// (https://blog.runevision.com/2026/03/fast-and-gorgeous-erosion-filter.html,
// building on Shadertoys by Clay John, 2018, and Fewes, 2023) as published
// in the MIT / MPL-2.0 licensed repository
// https://github.com/lpmitchell/AdvancedTerrainErosion (C# port copyright
// 2026 Luke Mitchell). The mathematics - the Phacelle stripe interpolation
// with partial circle normalization, the stacked fading of gully octaves
// toward the altitude-keyed fade target, the straight-gully slope
// accumulation, the ridge-map mask chain and the cubemap projection with
// face blending - follows the published filter 1:1. Two engine-side
// adaptations are documented at the implementation: the cell and corner
// hashing uses the module's int64 lattice-hash convention (the shader-style
// irrational hash of the original loses all fraction precision once seed
// magnitudes grow past ~32 bits, and the module's seeds are 64-bit), and
// every gully and terrain octave carries the module's low-pass band-limit
// fade so octaves finer than a consuming chunk's sampling cutoff drop out
// exactly like every other noise stream of the density field.
//
// Sampling is a pure function of (direction, cutoff, params, seed): safe to
// call from any thread in any order, and deterministic everywhere. The
// coarse relief the filter produces varies on landscape scales, so the
// public sample() evaluates it on a position-anchored interpolation lattice
// (the same convention the mesher's macro-climate grid uses) instead of
// re-running the full filter per voxel; sampleExact() exposes the raw
// filter for tools and single-point queries.

#pragma once

#include <cstdint>
#include <engine/planet/params.hpp>
#include <engine/planet/types.hpp>

namespace engine
{
namespace planet
{

// One evaluation of the eroded mountain field.
struct MountainErosionSample
{
    // Eroded height of the filter's own terrain: a band around 0.5 whose
    // width the terrain amplitude and erosion strength configure. The
    // consumer remaps it onto the mountain profile (see the erosion keys in
    // params.hpp).
    double height = 0.5;
    // Ridge map: -1 at gully creases (valley floors), +1 on ridge crests,
    // fading toward 0 where the terrain is too flat for either.
    double ridgeMap = 0.0;
};

class MountainErosionField final
{
public:
    MountainErosionField(const PlanetGenerationParams &params, std::int64_t seed);

    MountainErosionField(const MountainErosionField &) = delete;
    MountainErosionField &operator=(const MountainErosionField &) = delete;
    MountainErosionField(MountainErosionField &&) = default;
    MountainErosionField &operator=(MountainErosionField &&) = default;

    // Eroded relief for a surface direction. planetLocalPoint is the point
    // the relief is for, in planet-local meters - pass direction *
    // radiusMeters so every caller of a given direction shares lattice
    // cells. lowPassCutoffMeters follows the module's band-limit convention
    // (0 = full detail).
    //
    // denseSampling declares that the caller is walking a dense sample grid
    // around this point (the mesher's chunk lattices): the field then serves
    // the eroded relief from its shared corner lattice, which amortizes the
    // filter's cost across the many samples that land in one cell. Sparse
    // callers (probe rays, walker queries, octree selection) pass false and
    // get the exact filter per point - for them the lattice would evaluate
    // fresh corners for almost every query and cost several times MORE
    // than the filter itself. Both paths are pure functions of
    // (point, cutoff, params, seed), so a vertex shared between callers
    // reads consistent values either way.
    [[nodiscard]] MountainErosionSample sample(
        const Vec3 &planetLocalPoint, double lowPassCutoffMeters, bool denseSampling) const;

    // The raw filter at a unit direction: full evaluation cost, exact
    // values, no lattice. Tools and single-point queries use this.
    [[nodiscard]] MountainErosionSample sampleExact(const Vec3 &unitDirection, double lowPassCutoffMeters) const;

private:
    [[nodiscard]] MountainErosionSample sampleFaceExact(const Vec3 &unitDirection, double lowPassCutoffMeters) const;

    const PlanetGenerationParams *params_ = nullptr;
    std::int64_t seed_ = 0;
    // Identity of this field instance for the thread-local corner cache
    // (see the .cpp); assigned from a process-wide counter so interleaved
    // planets never read each other's cached corners.
    std::uint64_t fieldId_ = 0;
    // Lattice cell indices are packed into the cache key three times 20
    // bits (see the .cpp); the stride floor derived from the radius keeps
    // every supported planet inside that range.
    double latticeStrideFloorMeters_ = 1.0;
    // One p unit of the filter's 2D domain spans this many meters at the
    // cubemap face centers (the gnomonic projection stretches toward face
    // edges; see the .cpp).
    double metersPerUnit_ = 1.0;
};

} // namespace planet
} // namespace engine
